def exact_pin_occurs(value, pin):
    if type(value) is dict:
        if all(key in value and type(value[key]) is type(pin[key]) and value[key] == pin[key] for key in pin):
            return True
        return any(exact_pin_occurs(child, pin) for child in value.values())
    return type(value) is list and any(exact_pin_occurs(child, pin) for child in value)

def assignments(data):
    return {node.targets[0].id:node for node in ast.parse(data).body
        if isinstance(node,ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0],ast.Name)}

def functions(data):
    return {node.name:ast.dump(node,include_attributes=False) for node in ast.parse(data).body
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef))}

def protected_assignments(data):
    return {name:ast.dump(node,include_attributes=False) for name,node in assignments(data).items()
        if name not in CAPTURE_SLOTS}

def phase_assignment_bind(template, bound_sha, peer_sha):
    need(re.fullmatch('[a-f0-9]{64}',bound_sha) is not None and re.fullmatch('[a-f0-9]{64}',peer_sha) is not None,
        'two real canonical dependency digests, never guessed future Source pins')
    edits = []
    for variable,digest in (('BoundScriptSha256',bound_sha),('BoundReviewSha256',peer_sha)):
        old = '$'+variable+' = $null';new = '$'+variable+" = '"+digest+"'"
        need(template.count(old.encode()) == 1, 'exact original single phase binding assignment')
        start = template.index(old.encode())
        edits.append(dict(start_byte=start,end_byte=start+len(old),old=old,new=new))
    return splice_exact(template,edits)

def required_dependencies(stage, role):
    if stage == 'templates':return set()
    if stage == 'manifest':return set(TEMPLATE_ROLES)|{'profile'}
    if stage == 'capture':return {'capture_template','metadata_manifest','profile','static','metadata_peer'}
    if stage == 'phase_bound':return {role.replace('_bound','_template'),'capture_bound','metadata_binding','metadata_bound_review'}
    if stage == 'phase_binding':return set(TEMPLATE_ROLES[1:])|set(PHASE_BOUND_ROLES)|{'capture_bound','metadata_binding','metadata_bound_review'}
    raise ValueError('unknown deferred metadata stage')
